MAP
  NAME "demscore"
  STATUS ON
  IMAGETYPE PNG
  SIZE 1200 700
  EXTENT -180 -85 180 85
  UNITS DD
  MAXSIZE 10000

  PROJECTION
    "init=epsg:4326"
  END

  WEB
    METADATA
      "ows_enable_request" "*"
      "wms_title" "Demscore Hexagons"
      "wms_abstract" "Hexagon thematic map from Demscore variables in PostGIS"
      "wms_onlineresource" "http://localhost:8088/?map=/etc/mapserver/mapserver.map"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wms_allow_getmap_without_styles" "true"
      "wms_feature_info_mime_type" "text/plain"
      "wms_keywordlist" "demscore,hexagons,postgis"
    END
  END

  LAYER
    NAME "hex_variable"
    TYPE POLYGON
    STATUS ON
    EXTENT -20037508.34 -20037508.34 20037508.34 20037508.34
    CONNECTIONTYPE POSTGIS
    PROJECTION
      "init=epsg:3857"
    END
    CONNECTION "host=db port=5432 dbname=demscore user=demscore"
    DATA "geom FROM (SELECT hm.id_key || '_' || hm.hex_n AS id, cs.value, CASE WHEN '%polarity%' = 'positive' THEN (8 - cs.class_idx) WHEN '%polarity%' = 'neutral' THEN (10 + cs.class_idx) ELSE cs.class_idx END AS class_idx, cs.class_idx AS source_class_idx, cs.min_value, cs.max_value, hm.geom FROM demscore.hex_mesh hm JOIN demscore.country_scores('%dataset%','%variable%',%year%) cs ON cs.country_id = hm.country_id WHERE hm.hex_size_m = %hex_size% AND ST_Intersects(hm.geom, !BOX!)) AS hv USING UNIQUE id USING SRID=3857"
    PROCESSING "CLOSE_CONNECTION=DEFER"

    METADATA
      "wms_title" "Dataset Variable Hexagons"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wms_include_items" "all"
      "gml_include_items" "all"
    END

    VALIDATION
      "dataset" "^(qog|repdem|v_dem)$"
      "variable" "^[A-Za-z0-9_]+$"
      "year" "^[0-9]{4}$"
      "hex_size" "^[0-9]{5,7}$"
      "polarity" "^(positive|negative|neutral)$"
      "default_dataset" "v_dem"
      "default_variable" "v2x_polyarchy"
      "default_year" "2020"
      "default_hex_size" "200000"
      "default_polarity" "negative"
    END

    CLASS
      NAME "1"
      EXPRESSION ([class_idx] = 1)
      STYLE
        COLOR 49 54 149
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "2"
      EXPRESSION ([class_idx] = 2)
      STYLE
        COLOR 69 117 180
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "3"
      EXPRESSION ([class_idx] = 3)
      STYLE
        COLOR 116 173 209
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "4"
      EXPRESSION ([class_idx] = 4)
      STYLE
        COLOR 171 217 233
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "5"
      EXPRESSION ([class_idx] = 5)
      STYLE
        COLOR 253 174 97
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "6"
      EXPRESSION ([class_idx] = 6)
      STYLE
        COLOR 244 109 67
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "7"
      EXPRESSION ([class_idx] = 7)
      STYLE
        COLOR 215 48 39
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 1"
      EXPRESSION ([class_idx] = 11)
      STYLE
        COLOR 209 250 229
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 2"
      EXPRESSION ([class_idx] = 12)
      STYLE
        COLOR 167 243 208
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 3"
      EXPRESSION ([class_idx] = 13)
      STYLE
        COLOR 110 231 183
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 4"
      EXPRESSION ([class_idx] = 14)
      STYLE
        COLOR 52 211 153
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 5"
      EXPRESSION ([class_idx] = 15)
      STYLE
        COLOR 16 185 129
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 6"
      EXPRESSION ([class_idx] = 16)
      STYLE
        COLOR 5 150 105
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END

    CLASS
      NAME "neutral 7"
      EXPRESSION ([class_idx] = 17)
      STYLE
        COLOR 4 120 87
        OUTLINECOLOR 255 255 255
        WIDTH 0.25
      END
    END
  END

  # The black perimeter drawn around each run of same-coloured hexagons. It is a
  # layer of its own rather than a style on hex_variable, so the client can ask
  # for it by naming both layers in LAYERS and drop it by naming only the first.
  #
  # demscore.hex_borders holds every hexagon edge that could ever separate two
  # colours, precomputed per mesh in sql/mapserver_hex_setup.sql; the request
  # only has to keep the ones where the two sides landed in different classes.
  # A country with no value for this year is absent from country_scores, so its
  # side reads as a NULL class -- which IS DISTINCT FROM every real class, and
  # from NULL on the far side of a coastline edge it is not, so an area that is
  # not drawn is not outlined either.
  #
  # Class, not value, decides: two countries the legend paints the same shade are
  # one area whatever their underlying numbers. Polarity only relabels the
  # classes, so it cannot change which sides match and is not a parameter here.
  LAYER
    NAME "hex_outline"
    TYPE LINE
    STATUS ON
    EXTENT -20037508.34 -20037508.34 20037508.34 20037508.34
    CONNECTIONTYPE POSTGIS
    PROJECTION
      "init=epsg:3857"
    END
    CONNECTION "host=db port=5432 dbname=demscore user=demscore"
    DATA "geom FROM (SELECT hb.id, hb.geom FROM demscore.hex_borders hb LEFT JOIN demscore.country_scores('%dataset%','%variable%',%year%) a ON a.country_id = hb.country_a LEFT JOIN demscore.country_scores('%dataset%','%variable%',%year%) b ON b.country_id = hb.country_b WHERE hb.hex_size_m = %hex_size% AND a.class_idx IS DISTINCT FROM b.class_idx AND ST_Intersects(hb.geom, !BOX!)) AS ho USING UNIQUE id USING SRID=3857"
    PROCESSING "CLOSE_CONNECTION=DEFER"

    METADATA
      "wms_title" "Equal-Value Area Outlines"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wms_include_items" "all"
      "gml_include_items" "all"
    END

    VALIDATION
      "dataset" "^(qog|repdem|v_dem)$"
      "variable" "^[A-Za-z0-9_]+$"
      "year" "^[0-9]{4}$"
      "hex_size" "^[0-9]{5,7}$"
      "default_dataset" "v_dem"
      "default_variable" "v2x_polyarchy"
      "default_year" "2020"
      "default_hex_size" "200000"
    END

    CLASS
      NAME "area outline"
      STYLE
        COLOR 17 17 17
        WIDTH 1.6
        LINECAP ROUND
        LINEJOIN ROUND
      END
    END
  END
END
